package vn.thiendao.viethoa;
import android.app.*;import android.os.*;import android.content.*;import android.content.res.Configuration;import android.media.projection.*;import android.net.Uri;import android.provider.Settings;import android.graphics.drawable.GradientDrawable;import android.widget.*;import android.view.*;import java.util.Locale;
public class Main extends Activity {
 LinearLayout root; Spinner lang; int gold=0xffffd75b; int bg=0xff10182d;
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density);}
 void label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(8),0,dp(8));root.addView(t);}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(bg);GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{gold,0xffffa94e});g.setCornerRadius(dp(15));b.setBackground(g);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(54));p.setMargins(0,dp(6),0,dp(6));root.addView(b,p);b.setOnClickListener(v->r.run());}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(18),dp(22),dp(24));root.setBackgroundColor(bg);sc.addView(root);setContentView(sc);ImageView im=new ImageView(this);im.setImageResource(R.drawable.logo);root.addView(im,new LinearLayout.LayoutParams(dp(76),dp(76)));label("VIỆT HÓA HYPEROS",26,-1);label("PRO MAX  •  "+Build.MODEL,14,gold);label("DỊCH MÀN HÌNH",19,-1);lang=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Tiếng Trung → Tiếng Việt","Tiếng Anh → Tiếng Việt"});lang.setAdapter(a);root.addView(lang);button("Bật quyền hiển thị nổi",()->startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()))));button("Bắt đầu dịch màn hình",()->{if(!Settings.canDrawOverlays(this)){toast("Cần bật quyền hiển thị nổi");return;}MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);startActivityForResult(m.createScreenCaptureIntent(),42);});button("Dừng dịch màn hình",()->stopService(new Intent(this,ScreenService.class)));label("Lần đầu cần mạng để tải mô hình dịch. Sau đó có thể dịch ngoại tuyến. Chọn chia sẻ toàn màn hình khi Android hỏi.",14,0xffa9b8d4);label("NGÔN NGỮ HỆ THỐNG",19,-1);button("Kích hoạt locale tiếng Việt",()->locale("vi-VN"));button("Khôi phục locale trước đó",()->locale(getPreferences(0).getString("old","zh-CN")));button("Hướng dẫn cấp quyền ADB",()->new AlertDialog.Builder(this).setTitle("Cấp quyền bằng máy tính").setMessage("Bật USB debugging, kết nối máy tính và chạy:\n\nadb shell pm grant vn.thiendao.viethoa android.permission.CHANGE_CONFIGURATION\n\nHyperOS có thể từ chối quyền này. Locale không bổ sung bản dịch còn thiếu trong ROM.").setPositiveButton("Đóng",null).show());label("Bản dịch chỉ hiển thị trong lớp phủ. Không thay đổi ROM. Không chụp màn hình bảo mật.",14,0xffa9b8d4);}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void locale(String tag){try{Class<?> c=Class.forName("android.app.ActivityManager");Object svc=c.getMethod("getService").invoke(null);Class<?> api=Class.forName("android.app.IActivityManager");Configuration cfg=(Configuration)api.getMethod("getConfiguration").invoke(svc);if(!getPreferences(0).contains("old"))getPreferences(0).edit().putString("old",cfg.getLocales().get(0).toLanguageTag()).apply();cfg.setLocales(new LocaleList(Locale.forLanguageTag(tag)));api.getMethod("updatePersistentConfiguration",Configuration.class).invoke(svc,cfg);toast("Đã gửi yêu cầu đổi locale");}catch(Throwable e){toast("HyperOS không cho đổi locale. Kiểm tra quyền ADB hoặc dùng dịch màn hình.");}}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==42&&c==RESULT_OK&&d!=null){Intent i=new Intent(this,ScreenService.class);i.putExtra("code",c);i.putExtra("data",d);i.putExtra("chinese",lang.getSelectedItemPosition()==0);startForegroundService(i);moveTaskToBack(true);}}
}